+	if err != nil {
+		return err
+	}
+	repo := workspaceRepo{RepoKey: key, Name: addOpts.name, LocalPathHint: repoDir}
+	replaced := false
+	for i := range manifest.Repos {
+		if manifest.Repos[i].RepoKey == key {
+			manifest.Repos[i] = repo
+			replaced = true
