+		for _, repo := range manifest.Repos {
+			label := repo.RepoKey
+			if repo.Name != "" {
+				label = repo.Name + " (" + repo.RepoKey + ")"
+			}
+			fmt.Fprintf(&b, "- `%s`\n", label)
+		}
+	}
+	return b.String()
